// BAD — disables safety
function badHandler(e: any) {
  console.log(e.message); // compiles; crashes if e was "timeout"
}

// GOOD — forces a guard
function goodHandler(e: unknown) {
  if (!(e instanceof Error)) {
    console.log('non-Error throw:', e);
    return;
  }
  console.log(e.message);
}

// Library throws a string on timeout
function legacyParse(raw: string): object {
  if (!raw) throw 'empty payload'; // legal JS
  return JSON.parse(raw);
}

function naiveCatch() {
  try {
    legacyParse('');
  } catch (e: any) {
    metrics.increment('parse_fail', { msg: e.message }); // undefined — silent bad metric
  }
}

function safeCatch() {
  try {
    legacyParse('');
  } catch (e: unknown) {
    const err = toError(e);
    metrics.increment('parse_fail', { msg: err.message }); // "empty payload"
  }
}
